nginx:
server {
    server_name cine.nalexustechnologies.com;

    root /var/www/cineconnect/web;
    index index.html;

    # Flutter's release bundle is large. Make sure this vhost does not inherit
    # a per-request throttle and let Nginx stream/compress static assets.
    limit_rate 0;
    sendfile on;
    tcp_nopush on;
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_comp_level 6;
    gzip_types
        application/javascript
        application/json
        application/manifest+json
        application/octet-stream
        application/wasm
        application/xml
        font/otf
        font/ttf
        image/svg+xml
        text/css
        text/javascript
        text/plain;

    location /.well-known/acme-challenge/ {
        root /var/www/cineconnect/bootstrap;
        try_files $uri =404;
    }

    client_max_body_size 260m;

    # Host-managed routes used by the Nalexus monitoring/SEO services.
    include /etc/nginx/snippets/nalexus-agent.conf;
    include /etc/nginx/snippets/nalexus-seo-agent.conf;

    location ^~ /media/ {
        proxy_pass http://127.0.0.1:5002/api/v1/media/;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
    }

    # Keep API traffic on Gunicorn while Nginx serves the Flutter application.
    location = /cineconnect_push.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }
    location = /cineconnect_push_worker.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location /api/ {
        proxy_pass http://127.0.0.1:5002;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
    }

    # Entry points must revalidate so a deployment cannot strand browsers on
    # a stale service worker or an old HTML bootstrap file.
    location = /index.html {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = / {
        try_files /index.html =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = /flutter_service_worker.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = /flutter_bootstrap.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = /version.json {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = /director_tutorial.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = /director_tutorial.css {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    location = /director_tutorial_bootstrap.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, no-store, must-revalidate" always;
    }

    # The HTML bootstrap appends the release/service-worker version to this
    # stable filename. Cache that versioned URL so returning visits do not
    # download the multi-megabyte Flutter bundle again; every deployment gets
    # a different query string and therefore a fresh browser cache entry.
    location = /main.dart.js {
        try_files $uri =404;
        add_header Cache-Control "no-cache, must-revalidate" always;
    }

    location ~* \.(?:wasm|mjs|js|css|png|jpe?g|gif|webp|svg|ico|woff2?|ttf|otf)$ {
        try_files $uri =404;
        add_header Cache-Control "public, max-age=86400" always;
        access_log off;
    }

    # Flutter uses hash routes today, but this fallback also keeps path-based
    # bookmarks and future URL-strategy routes working.
    location / {
        try_files $uri $uri/ /index.html;
    }

    listen [::]:443 ssl; # managed by Certbot
    listen 443 ssl; # managed by Certbot
    ssl_certificate /etc/letsencrypt/live/cine.nalexustechnologies.com/fullchain.pem; # managed by Certbot
    ssl_certificate_key /etc/letsencrypt/live/cine.nalexustechnologies.com/privkey.pem; # managed by Certbot
    include /etc/letsencrypt/options-ssl-nginx.conf; # managed by Certbot
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem; # managed by Certbot

}
server {
    if ($host = cine.nalexustechnologies.com) {
        return 301 https://$host$request_uri;
    } # managed by Certbot


    listen 80;
    listen [::]:80;
    server_name cine.nalexustechnologies.com;
    return 404; # managed by Certbot


}
